mapper.select:
select id, order_id, user_id, team_id, activity_id, product_id, product_name, quantity, source, channel, original_amount, deduction_amount, pay_amount, status, out_trade_no, create_time, update_time from group_buy_order
out_trade_no = #{outTradeNo}
and user_id = #{userId}
limit 1

select count(id)
from group_buy_order
where user_id = #{userId}
  and activity_id = #{activityId}

mapper.update:
update group_buy_order
set status = 1,
    update_time = now()
where user_id = #{userId}
  and out_trade_no = #{outTradeNo}
  and status = 0
